const freeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;};
freeze(LT_IMPACT_PROFILES);
export const ltImpactSource=id=>LT_IMPACT_PROFILES[id]??null;
export const ltImpactSiblings=profile=>Object.values(LT_IMPACT_PROFILES).filter(p=>p.equipmentId===profile.equipmentId);

export function ltImpactGripPolicy(profile){
 if(!ltImpactSource(profile?.modeId))return null;
 if(profile.unarmedSkillBonus)return {grips:[],twoHanded:false,reason:'Табличный удар сжатой рукой; хват уже включён в профиль. LT65; LT71[5].'};
 const siblings=ltImpactSiblings(profile),twoHanded=siblings.some(p=>p.hands===2);
 const thrust=siblings.some(p=>/^thr/.test(p.stats.damage));
 const tooLong=siblings.some(p=>/[3-9]/.test(p.stats.reach));
 return {grips:['defensive',...(thrust&&!tooLong?['reversed']:[])],twoHanded,
  reason:tooLong?'Обратный хват оружия длиннее Reach2 не подтверждён. MA111.':!thrust?'Нет опубликованного колющего режима для Reversed Grip. MA111.':null};
}

export function ltImpactHints(profile){
 if(!ltImpactSource(profile?.modeId))return [];
 const out=[];
 if(['lt:jo','lt:quarterstaff','lt:long-staff'].includes(profile.modelId))out.push('Табличный Staff уже включает +2 Parry. Two-Handed Sword использует отдельные строки Damage, Reach, ST и Parry. LT65,69–70.');
 if(profile.modelId==='lt:tetsubo')out.push('Two-Handed Axe/Mace и Two-Handed Sword используют отдельные опубликованные строки; их параметры не складываются. LT70.');
 if(profile.modelId==='lt:short-baton')out.push('Shortsword и Knife используют собственные defaults. Swing и Thrust имеют разные Reach. LT67,69.');
 if(['lt:macuahuitl','lt:macuahuilzoctli','lt:two-handed-macuahuitl'].includes(profile.modelId))out.push('Обсидиановая кромка: затупление, потеря cutting Damage и ремонт учитываются вручную. Обычный дробящий Thrust не получает бонус кромки. LT59.');
 if(profile.stats.reach.includes('*'))out.push('Для смены отмеченного Reach требуется Ready; решение о смене и действие учитывает игрок. B269.');
 if(profile.unarmedSkillBonus)out.push('Табличный Damage уже включает fist load. Бонус изученного Boxing/Brawling/Karate учитывается один раз для выбранного навыка. LT65; LT71[5]; B182,203.');
 if(profile.modelId==='lt:tonfa')out.push('Tonfa: можно использовать Brawling/Karate Parry, если он лучше. В Reversed Grip специальное парирование без дополнительного штрафа; последствия неудачного Parry – вручную. LT64,70[12]; MA111.');
 if(profile.modelId==='lt:jutte')out.push('Jitte/Sai: +2 к обезоруживанию вручную. Main-Gauche использует Parry F; фехтовальные ограничения применяет игрок. LT66–67; LT71[11].');
 if(['lt:pick','lt:warhammer'].includes(profile.modelId))out.push('Оружие может застрять; извлечение и сопротивление – вручную. Штраф за щели в доспехе уменьшается на 2 вручную. LT65,70–71[3,4]; B405.');
 if(['lt:axe','lt:mace','lt:round-mace','lt:throwing-axe'].includes(profile.modelId))out.push('Одноручная и двуручная атаки – разные опубликованные строки. Defensive Grip является отдельным хватом. LT54,58,64–65,70; MA111.');
 if(profile.modelId==='lt:gada'&&/^thr/.test(profile.stats.damage))out.push('Thrust: удар с удержанием рядом с головкой. Смена хвата/Reach требует Ready; автоматического учёта времени нет. LT56,70; B269.');
 if(profile.modelId==='lt:blackjack')out.push('Скрытые ушибы: Diagnosis−2 для обнаружения при беглом осмотре, вручную. LT54.');
 if(profile.modelId==='lt:myrmex')out.push('Myrmex: DR1 только кисти, вручную; не складывать с другими перчатками. LT71[6].');
 if(profile.modelId==='lt:cestus')out.push('Cestus: DR4 только кисти, вручную. Удлинённый вариант и Elbow Strike остаются особыми процедурами (?). LT55; LT71[6].');
 if(profile.modelId==='lt:combat-fan'&&profile.attackModifier)out.push('Режущая атака Combat Fan: прямой штраф −2 к навыку уже учтён. LT65.');
 if(['lt:baton','lt:light-club','lt:short-staff'].includes(profile.modelId))out.push('Cane использует Light Club, лёгкая трость – Short Staff. Жёсткие ножны не легче 1 lb используют Baton и Cheap для поломки. Hook остаётся ручным действием. LT55,57.');
 if(!out.length)out.push('Опубликован только Swing; отдельный Thrust не задан. Ограничения парирования и поломку учитывает игрок. LT65; B269,376.');
 return out;
}

// Published LT71[5] bonuses, distinct from the fist-load +1 already in thr cr.
export function ltImpactSkillDamage(profile,skillName,skill,actor){
 if(!profile?.unarmedSkillBonus)return null;
 const dx=Number(actor?.system?.attributes?.DX?.value),level=Number(skill?.sourceLevel??skill?.level);
 let bonusPerDie=0;
 if(skill?.source==='learned'&&Number.isFinite(dx)&&Number.isFinite(level)){
  const relative=level-dx;
  if(skillName==='Brawling')bonusPerDie=relative>=2?1:0;
  if(skillName==='Boxing')bonusPerDie=relative>=2?2:relative>=1?1:0;
  if(skillName==='Karate')bonusPerDie=relative>=1?2:relative>=0?1:0;
 }
 return {name:skillName,source:'LT71[5]; B182,203',bonusPerDie};
}

export function applyLTImpactSourceMode(mode,equipment,{snapshot=false}={}){
 const p=ltImpactSource(mode?.weapon_mode_id);
 if(!p||equipment?.source!=='LT'||equipment.equipment_id!==p.equipmentId)return mode;
 const before=p.sourceFieldsBefore;
 if(!snapshot||!before||[before.damage,p.stats.damage].includes(mode.raw_calc?.damage)){
  const m=/^(sw|thr)([+-]\d+)?(?:\(([\d.]+)\))?\s+(\S+)$/.exec(p.stats.damage);
  if(!m)throw Error('Invalid verified LT impact Damage');
  mode.raw_calc={...mode.raw_calc,damage:p.stats.damage};
  const damage={...mode.stats.damage,st:m[1],type:m[4]};
  if(m[2])damage.base=String(Number(m[2]));else delete damage.base;
  if(m[3])damage.armor_divisor=Number(m[3]);else delete damage.armor_divisor;
  mode.stats.damage=damage;
 }
 for(const [key,field]of [['reach','reach'],['parry','parry'],['strength','st']])
  if(!snapshot||!before||[before[field],p.stats[field]].includes(mode.stats[key]))mode.stats[key]=p.stats[field];
 if(!snapshot||!before||[before.usage,p.usage].includes(mode.usage))mode.usage=p.usage;
 mode.lt_impact_contract={modelId:p.modelId,sourcePages:p.sourcePages,damagePart:p.damagePart,hands:p.hands};
 return mode;
}

export function projectLTImpactSourceData(book,data){
 if(book!=='weapons')return data;
 for(const equipment of data.equipment){
  if(equipment.source!=='LT')continue;
  for(const p of Object.values(LT_IMPACT_PROFILES).filter(p=>p.equipmentId===equipment.equipment_id&&p.templateModeId))
   if(!equipment.modes.some(m=>m.weapon_mode_id===p.modeId)){
    const template=equipment.modes.find(m=>m.weapon_mode_id===p.templateModeId);
    if(template){const mode=structuredClone(template);mode.weapon_mode_id=p.modeId;equipment.modes.push(mode);}
   }
 }
 return data;
}
